package com.example.spring.chapter29;

import java.util.stream.Stream;

public class IntermediateShortCircuit {
    public static void main(String[] args) {
        // An infinite stream of even numbers generated by Stream.iterate
        Stream.iterate(0, n -> n + 2)
                .limit(5) // Short-circuits the infinite the stream to just 5 elements
                .forEach(System.out::println);
    }
}
